import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Template rendering - custom lightweight engine
function renderTemplate(templateName, context) {
  const templatePath = `./templates/${templateName}.html`;
  let template = fs.readFileSync(templatePath, 'utf8');

  // Replace {{variable}} patterns with context values
  for (const [key, value] of Object.entries(context)) {
    const regex = new RegExp(`\\{\\{\\s*${key}\\s*\\}\\}`, 'g');
    template = template.replace(regex, String(value));
  }
  return template;
}

// Middleware: extract tenant from subdomain
app.use((req, res, next) => {
  const host = req.headers.host || '';
  const parts = host.split('.');
  req.tenantId = parts.length > 2 ? parts[0] : 'default';
  next();
});

// Search endpoint - returns HTML page with results
app.get('/search', async (req, res) => {
  const { q, page = '1', format = 'html' } = req.query;

  if (!q || typeof q !== 'string') {
    return res.status(400).json({ error: 'Missing search query' });
  }

  const pageNum = Math.max(1, Math.min(100, parseInt(page) || 1));
  const offset = (pageNum - 1) * 20;

  try {
    // Parameterized query - safe from SQLi
    const result = await pool.query(
      'SELECT id, title, snippet, author FROM articles WHERE tenant_id = $1 AND search_vector @@ plainto_tsquery($2) ORDER BY ts_rank(search_vector, plainto_tsquery($2)) DESC LIMIT 20 OFFSET $3',
      [req.tenantId, q, offset]
    );

    if (format === 'json') {
      return res.json({ results: result.rows, query: q, page: pageNum });
    }

    // Render HTML with search results
    const resultsHtml = result.rows.map(row => 
      `<div class="result"><h3><a href="/article/${row.id}">${row.title}</a></h3><p>${row.snippet}</p><span class="author">${row.author}</span></div>`
    ).join('');

    const html = renderTemplate('search', {
      query: q,
      results: resultsHtml,
      page: pageNum,
      tenant: req.tenantId,
      resultCount: result.rows.length,
      nonce: crypto.randomBytes(16).toString('hex')
    });

    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Article detail endpoint
app.get('/article/:id', async (req, res) => {
  const id = parseInt(req.params.id);
  if (isNaN(id)) return res.status(400).json({ error: 'Invalid ID' });

  const result = await pool.query(
    'SELECT id, title, body, author, created_at FROM articles WHERE id = $1 AND tenant_id = $2',
    [id, req.tenantId]
  );

  if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });

  const article = result.rows[0];
  const html = renderTemplate('article', {
    title: article.title,
    body: article.body,
    author: article.author,
    date: article.created_at
  });

  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.send(html);
});

// Health check
app.get('/healthz', (req, res) => res.json({ status: 'ok' }));

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0');
